INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madoro-Mu', 'Madoro-Mu is a traditional Yume Nikki fangame. It stars Isokishi who, unlike most fangames, uses her bed to save and exits her room directly to the Nexus. Rather than having a nexus full of doors, Isokishi''s nexus consists of three windows. One is nailed shut until later in the game. There is little to no sound in the game.' FROM games WHERE igdb_id = 166436 ON CONFLICT (game_id, language_code) DO NOTHING;
