INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lost Cases of Sherlock Holmes 2', 'Return to 221 Baker St. and play as the famous Sherlock Holmes to solve 16 mysterious crimes in Victorian England. Dust off your magnifying glass and use your astute observational skills to gather evidence in 60 brilliantly rendered locations around Victorian England including Stonehenge, Marlsbury Castle, London''s Music Hall and more! Unlock vital clues by playing over 50 mind-bending puzzles and mini-games in each case, including anagrams, cryptograms, and more. Featuring over 40 levels of hidden object and find the difference gameplay with more than 100 lively characters, including Watson, Mycroft, and Inspector Lestrade. Each clue leads you closer to catching the culprit!' FROM games WHERE igdb_id = 10979 ON CONFLICT (game_id, language_code) DO NOTHING;
