INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JumpStart: Get Moving Family Fitness Sports Edition featuring Brooke Burke', 'Get your family moving and find how fitness can be fun! For years, JumpStart has been creating the best learning games for kids. Now, with Get Moving Family Fitness, JumpStart is making fitness fun too! Discover the ultimate family sports game with fitness expert and mom of 4, Brooke Burke. With more than 15 sports challenges in 11 exotic arenas, Get Moving is the fun, new way to keep your family active!' FROM games WHERE igdb_id = 50663 ON CONFLICT (game_id, language_code) DO NOTHING;
