INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elemental Monster: Online Card Game', 'In Elemental Monster, winning is everything. Practice makes perfect through the single player competition with over 10 hours of gameplay. Once ready, gamers can take their skills online via the PlayStation Network and jump into the arena. Winning online tournaments allow unlocks to exclusive emblems and rise up in the world-wide ranks, but it will also open up access to exclusive cards with all-new powers, attacks and abilities.' FROM games WHERE igdb_id = 94071 ON CONFLICT (game_id, language_code) DO NOTHING;
