INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'G-Switch', 'Become a gravity-controlling mastermind to win the race! G-Switch lets you flip the direction of gravity. Whenever you are running, you can invert yourself to avoid danger. Hit checkpoints in solo mode, or compete with 5 other players in a futuristic sprinting tournament!' FROM games WHERE igdb_id = 348089 ON CONFLICT (game_id, language_code) DO NOTHING;
