INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of the Vampire', 'Legend of the Vampire is an RPG style game with anime visualization. In the game, you have to play as one of the vampires or paladins who fights against vampires. You will be able to fight with friends and other players, get a pet, find a companion and propose to her. Choose a mage, archer, or swordsman character type and go in search of adventures and new friends.' FROM games WHERE igdb_id = 335001 ON CONFLICT (game_id, language_code) DO NOTHING;
