INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AbbleDabble', 'Abble Dabble is the revolution of crossword games with classic word play with a new twist. Expand your game. It''s like yoga for your mind. Moving Bonus Tiles: Crossword strategy jumps to the next level with the option of moving bonuses. Can you out-maneuver your opponent to tap the best combination of bonuses? Or play on a traditional static board choosing from several bonus patterns.' FROM games WHERE igdb_id = 174319 ON CONFLICT (game_id, language_code) DO NOTHING;
