INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Muv-Luv Unlimited: The Day After - Episode 00', 'Picking up directly where Muv-Luv Unlimited left off, witness the aftermath of Alternative V, as the last remnants of humanity fight a desperate battle for survival on a barren and desolate Earth! Featuring a brand-new cast (with some returning fan-favorites thrown in for good measure!) and all-new challenges to face, this epic four-part saga is sure to please longtime fans and newcomers alike!
