INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trick DS Ban: Kakushigami no Sumu Yakata', 'A series of mysterious disappearances occur in an old mansion in a mountain village. Based on the Japanese TV drama TRICK, the player can investigate as either aspiring magician Naoko or skeptical physicist Ueda, working together to collect evidence and testimony from witnesses, track down the real culprit, and uncover the hidden ''trick'' to the supposedly supernatural happenings.' FROM games WHERE igdb_id = 329949 ON CONFLICT (game_id, language_code) DO NOTHING;
