INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Icarus-X', 'Icarus-X is a Full 3D Vertical Shooter, featuring fast paced action, epic boss battles, challenging achievements, downloadable replays and the mandatory online leaderboards! Icarus-X is now Universal and supports Retina Display, Game Center and the new iPhone 5.Icarus-X features downloadable replays, so that you can enjoy watching the best players in the world turn the game inside out and pull out gigantic high scores!There is also a Slow-Motion Pratice mode to learn the more difficult patterns at your own pace.' FROM games WHERE igdb_id = 341074 ON CONFLICT (game_id, language_code) DO NOTHING;
