INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castaway', 'Stranded on a mysterious island, it is up to you to restore peace to its villagers. Become a powerful warrior - growing your powers and abilities through over 50 quests across a distinct and visually stylized world. Discover and raise loyal pets that will fight by your side in this unique action RPG. Customize your appearance as you gain new armor and weapons from wooden sticks to elemental swords.' FROM games WHERE igdb_id = 187063 ON CONFLICT (game_id, language_code) DO NOTHING;
