INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tractor Racing Simulation', 'Experience the life of tractor driver with this awesome new tractor Simulator. Drive your tractor in an exciting journey to the lands of pure nature and vividness through lush Meadows and Green fields, carrying goods from the outskirts areas to your farm. The tractor will be derailed if not handled carefully on turning. Race against time in this tractor driving Simulator, collect Gold from the outskirts farmers and then drive back to your own farm in limited time.Have fun while driving tractor in this tractor Simulator and become a pro tractor driver.' FROM games WHERE igdb_id = 142748 ON CONFLICT (game_id, language_code) DO NOTHING;
