INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-otherside-realm-of-eons', 16163, '2010-01-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/vrwr6xdxtgmaii8dlfha.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/h3bzqvo4fud8jsxtzcf7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Otherside: Realm of Eons', 'After receiving an anonymous package containing a strange book, Miranda finds herself inadvertatly drawn into the fantastic world of The Otherside. With the guidance of the mischevious Jovie, a possessed teddy bear, she must travel back and forth between worlds and help to unravel the mystery of a brother and sister torn apart. All is not as it seems in this realm of secrets and enigmas, and you must help Miranda to solve the many riddles that lay within. Enlist the mysterious Michael''s help and watch the story unfold through animated in-game comics. Journey through over 25 beautifuly detailed locations as you discover all the objects hidden throughout. Combine various items to create new tools to help you further your quest. Solve over 10 puzzling minigames to help Miranda locate the missing Louise and save her from a ghastly fate. It''s up to you to help Miranda save the day and unravel the mysteries of The Otherside: Realm of Eons.' FROM games WHERE igdb_id = 16163 ON CONFLICT (game_id, language_code) DO NOTHING;
