INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wildlife Camp', 'Discover new animal species, nurse them back to health and care for them. Look after your little camp with its cute and extraordinary residents. Enjoy some breathtaking encounters with exotic animals, and experience direct contact with the animals and their environment. Besides their medical care, your daily routine includes rearing animals with a bottle and fun activities such as elephant riding.' FROM games WHERE igdb_id = 36063 ON CONFLICT (game_id, language_code) DO NOTHING;
