INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hatsune-miku-project-diva-arcade', 11771, '2010-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaurk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nzlqmngmtgm0jd3lrgpj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hatsune Miku: Project Diva Arcade', 'Hatsune Miku: Project DIVA Arcade is an arcade rhythm game. The game is a port of the 2009 video game, Hatsune Miku: Project DIVA, with updated visuals. The gameplay is relatively the same as the original. The signature PlayStation buttons, cross, circle, square and triangle are now the 4 large buttons on the machine''s panel, and players push those buttons to play the games. Unlike the handheld versions of the game, players can hold a button or buttons for an unlimited time when the game indicates to hold a certain note. This will allow players to receive a bonus which continuely increases the score until the player releases one of the held button or a "Max Hold Bonus" is granted. Another difference is that multiple buttons can be hit at the same time up to all four buttons. The arcade version features songs from both Hatsune Miku: Project DIVA series and Hatsune Miku and Future Stars: Project Mirai, along with a variety of original songs not included in either of the handheld versions. The Promotional Videos for the game, which are the videos playing in the background during a song have been updated and re-rendered for the game bearing a similar resemblance to the Dreamy Theatre versions of the PVs.' FROM games WHERE igdb_id = 11771 ON CONFLICT (game_id, language_code) DO NOTHING;
