INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mechanic Man', 'The evil scientist Dr. Bronze has stolen manufacturing equipment in order to assemble his own army of killer robots! Join our brave hero, Steel, as he journeys to take down the CU brand androids and storm Bronze’s facility to save the world. Run, jump, and shoot through ten stages filled with dangerous foes, tight platforming and intimidating bosses. It’s now or never, so fight, Steel! For everlasting peace!' FROM games WHERE igdb_id = 318900 ON CONFLICT (game_id, language_code) DO NOTHING;
