INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('armored-core-last-raven-portable', 38480, '2010-06-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co48ot.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armored Core: Last Raven Portable', 'In the wake of the now defunct Navis''s failed attempt to control recovered ancient weapons technology, the world has been left in tatters. Looking to consolidate power, the Corporations (Crest, Mirage, and Kisaragi) have merged into one super-corporation known as "The Alliance". Fed up with corporate rule and oppression, and seeing a newfound threat in The Alliance, a Raven known as Jack-O (an important but minor character from Armored Core: Nexus) forms an organization of Ravens known as "Vertex" from the ashes of the fallen Raven''s Ark. After rallying a sizable force of fellow Ravens to his cause, Jack-O declares that he will launch an all-out war on the Alliance in 24 hours. Leading the opposing force, a Raven named Evangel has rallied just as many Ravens to the Alliance and is preparing to fight Jack-O head on. Making matters all the more complicated, many Ravens have turned into independent warlords, setting out on their own after the collapse of Raven''s Ark.
