INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dale and Peakot', 'Play Dale And Peakot, a great action platform / puzzle game. Take two roles as Dale the farmer with a shotgun as well as Peakot his sidekick chicken with an attitude. Use Dale to take out bad guys, but the twist is you control Peakot at the same time to fly around and hit levers and switches. Try to solve your way out of eggy situations, and get back the stolen hens that have been captured by the coyotes.' FROM games WHERE igdb_id = 270736 ON CONFLICT (game_id, language_code) DO NOTHING;
