INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbie: Groom and Glam Pups', 'Barbie Groom & Glam Pups is an all-new, fun and engaging game that lets players choose a pup from one of six adorable breeds, then groom it, train it, and dress it up. Finally, players show off their glam pup in a fabulous dance sequence, runway show and photo shoot.' FROM games WHERE igdb_id = 3316 ON CONFLICT (game_id, language_code) DO NOTHING;
