INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Heroes: Zero no Kiseki', 'The Legend of Heroes: Zero no Kiseki is the fourth installment in the main Kiseki series, serving as a direct sequel to the events of the Liberl arc and the beginning to the Crossbell arc. The game follows Lloyd Bannings and his colleagues Elie MacDowell, Randy Orlando, and Tio Plato. The four form the Special Support Section, a newly formed department of the Crossbell police in a city-state located between two great powers fighting for control over it.' FROM games WHERE igdb_id = 192133 ON CONFLICT (game_id, language_code) DO NOTHING;
