INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ys Seven: Premium Edition', 'The seventh installment of the popular RPG series (and first developed exclusively for PlayStation Portable) tells the story of the Five Great Dragons of Altago. The battle system consists of a three-member battle party with enemies engaged on the field map in real-time for fast-paced combat. Old fans of the series and new players alike will be immersed into the rich vibrant world containing over 30 hours of gameplay.' FROM games WHERE igdb_id = 42691 ON CONFLICT (game_id, language_code) DO NOTHING;
