INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gangster-city', 342483, '2010-01-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9rd9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwoh1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gangster City', 'This is what it means to be a real gangster. If they''re mean, you need to be meaner. If they''re tough, you need to be tougher. If they hit you you need to hit them right back so hard they don''t get up. You need a sharp suit, the most tricked out wheels in the district and a whole lot of friends to back you up. You need to run missions for the mob that make Delta Force look like kindergarten. You need to get neck deep in the enemy territory and come out covered in blood. Theirs, not yours. You need a city to make your own and the people who walk its streets to get on their knees and call you king. But most of all you need guns. Lots and lots of guns.
