INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thomas & Friends: Hero of the Rails', 'Play as Thomas for the first time ever on Nintendo Wii! Help get Hiro back on the tracks! Play Thomas karaoke Play the game which includes detailed 3D versions of your favourite characters including Thomas, Percy and Hiro! Race the engines, toot your whistle and complete activities such as painting Thomas, and sorting parts. Take part in 8 activities and journeys to find parts needed to fix Hiro so he can return home.' FROM games WHERE igdb_id = 50712 ON CONFLICT (game_id, language_code) DO NOTHING;
