INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bounce On 2: Drallo''s Demise', 'Roll your way through the Floating Ruins, explore space on the Orbital Platform, and finish the fight in Drallo''s Fortress. Customize your character, find hidden secrets, fight against unique bosses and collect gems! With different level objectives to select, and over 100 keys to collect, Bounce On 2: Drallo''s Demise will keep you playing and playing!
