INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reeelz', 'You have seven reeelz. Spin them, lock them and even step them one by one to make combos and take down all the combo cards. Do not rush for all the easy combos, or you will hit your token limit and have a very hard endgame. Pick your moves wisely, each spin or step costs one token.Run out of tokens and lose, or take down all the combo cards and win! Have a great time playing!' FROM games WHERE igdb_id = 348952 ON CONFLICT (game_id, language_code) DO NOTHING;
