INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Epic Mickey: Path Painter', 'Epic Mickey: Path Painter is an online flash game released by Disney Interactive Studios, developed by Sarbakan in 2010. Based on the original Wii game, Epic Mickey, it is an isometric point and click adventure through Wasteland where players can use paint and thinner to influence the world around them. The game has since been removed from Disney''s websites.' FROM games WHERE igdb_id = 361434 ON CONFLICT (game_id, language_code) DO NOTHING;
