INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightfall Mysteries: Curse of the Opera', 'Take on the role of a lowly stagehand in an opera company tasked with solving a deadly mystery! The Opera troupe is invited by the reclusive Count Vladd Vansig III to his small hamlet to perform a special Opera for him. Strangely, there are no villagers to speak of except for the Count and his caretaker. Over the course of the night, people go missing and are killed! Use your Hidden Object skills to find out the identity of the killer and escape the village alive in Nightfall Mysteries: Curse of the Opera!' FROM games WHERE igdb_id = 125308 ON CONFLICT (game_id, language_code) DO NOTHING;
