INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1001 Nights: The Adventures of Sindbad', 'Help the lovely Princess Chalida locate the seven gems of her royal crown and break the curse that has trapped her in a body of wood! Find Hidden Objects, identify specific spots in each scene, and overcome powerful guardians as you seek out the precious stones. Along the way you''ll have to solve dozens of clever riddles and beat eight challenging minigames, in 1001 Nights: The Adventures of Sinbad!' FROM games WHERE igdb_id = 52342 ON CONFLICT (game_id, language_code) DO NOTHING;
