INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cow Clicker', 'A self-described "Facebook game about Facebook games", Cow Clicker was a game in which players earned points by clicking on a cow every six hours, with microtransactions for timer overrides and premium cow designs. Though intended as a satire of of game design trends, the game was unexpectedly popular and it is now recognized as an early example of the clicker or idle game genre.' FROM games WHERE igdb_id = 144482 ON CONFLICT (game_id, language_code) DO NOTHING;
