INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kung Fu Funk', 'Kung Fu Funk takes you back to when martial arts had style and colours were either vibrant or beige. Enter this world of big hair and flared pants in your very own Kung Fu movie styled game. Meet the challenge with your friends and family in this unique martial arts party experience; master the Zen arts of Tai Chi in preparation for the Kung Fu training montage of mini games, then unleash your training in the disco dojo.' FROM games WHERE igdb_id = 67190 ON CONFLICT (game_id, language_code) DO NOTHING;
