INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Soujinengi: The Genius of Sappheiros', 'Touhou Soujinengi: The Genius of Sappheiros is a fan-made Touhou Project game and a traditional turn-based RPG released at Comiket 78, heavily influenced by traditional console roleplaying games such as the SaGa Series. Despite being an RPG, it follows a traditional Touhou stage-based format, with each stage being its own dungeon.' FROM games WHERE igdb_id = 65194 ON CONFLICT (game_id, language_code) DO NOTHING;
