INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamen Rider: Climax Heroes OOO', 'Kamen Rider: Climax Heroes OOO is a Japanese fighting game developed by Eighting and Bandai Namco Entertainment for the PlayStation Portable and Nintendo Wii. Serving as the sequel to Climax Heroes W, it is the third installment of the Kamen Rider: Climax series and features all Heisei-era Riders up until OOO as playable characters. A sequel featuring Fourze was released in 2011.' FROM games WHERE igdb_id = 64240 ON CONFLICT (game_id, language_code) DO NOTHING;
