INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lucky Tower', 'Lucky Tower is an escape game that lets you play as a knight stuck in a tower, and your only goal is to escape. Pick a door to go through on each floor to find out if it will take you one step closer to the exit or if it will serve you your death with a funny little animation. Escaping the tower without dying is near impossible, so brace yourself!' FROM games WHERE igdb_id = 219067 ON CONFLICT (game_id, language_code) DO NOTHING;
