INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hinokakera Chaotic Eclipse', 'The fourth major version of Hinokakera, following in the footsteps of its predecessors with its mix of 2D and 3D fighter mechanics. Tweaks have been made to the combat system and character balance, but most importantly, this version features noticeably updated visuals, a replay system and a netplay client integrated to the game itself.' FROM games WHERE igdb_id = 146153 ON CONFLICT (game_id, language_code) DO NOTHING;
