INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aporkalypse: Pigs of Doom', 'We have a pig problem! According to an old prophecy the four Pigs of Doom should proclaim the end of the world in a distant future. But something went terribly wrong and the gates of heaven and hell have already opened! Now it is up to the greedy Hunger Pig, the heavily armed War Pig, the contaminous Pest Pig and the ghostly Death Pig to stop this madness.' FROM games WHERE igdb_id = 333544 ON CONFLICT (game_id, language_code) DO NOTHING;
