INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlefield: Bad Company 2 Ultimate Edition', 'The game is primarily a squad-level first-person shooter based in a contemporary modern warfare setting. Additionally, the game includes a single-player campaign, where the player re-assumes the role of Preston Marlowe, the protagonist of the original game. The game''s Frostbite 1.5 engine allows for destructible environments. Multiplayer maps, which allow for five different game modes, contain a wide selection of vehicles, aircraft and emplacements' FROM games WHERE igdb_id = 41892 ON CONFLICT (game_id, language_code) DO NOTHING;
