INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Remnants of Skystone', 'Remnants of Skystone was a 2D side-scrolling platformer in a steampunk post-apocalyptic setting with multiplayer elements. Players could play as one of the three playable classes (Aeronaut, Crag or Ferric), each with different abilities, and travel to different parts of Nidaria or Etherea. Missions and Quests were the main single-player elements and Trailblazing was the main multiplayer element.' FROM games WHERE igdb_id = 270283 ON CONFLICT (game_id, language_code) DO NOTHING;
