INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Freeway Fury', 'Stuck in traffic? Don''t let that stop you! Jump between cars and switch vehicles at anytime in this fast-paced arcade racer. Do crazy stunts for extra points and nitro boost! Tilt to steer and press the nitro button for extra speed. Tap anywhere on the screen to jump in that direction. Land on vehicles to take control of them, or else you''re roadkill! Reach the next checkpoint before the time ends! So what are you waiting for? Release your fury!!!' FROM games WHERE igdb_id = 175859 ON CONFLICT (game_id, language_code) DO NOTHING;
