INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nickelodeon Fit', 'Nickelodeon Fit is a children''s fitness game for Wii featuring Nickelodeon''s favorite characters Dora, Diego, Kai-lan and The Backyardigans in one game. Packed with 30 scientifically developed and designed exercises that target a variety of fitness areas important for healthy physical development in children, Nickelodeon Fit is the perfect way for parents to ensure that their young children remain active as they are entertained by their favorite cartoon characters. Additional features include: Wii Remote and Wii Balance Board input options and play monitoring and customization functionality for parents to observe their children''s progress and plan their exercise routine.' FROM games WHERE igdb_id = 50706 ON CONFLICT (game_id, language_code) DO NOTHING;
