INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Dream World', 'Online browser game of the now shut-down Pokémon Global Link, where players could play minigames to gain Pokémon outside of the main game and grow berries, both to send to the main game (Pokémon Black/White) via the Entralink. Had social features as well, such as a customizable house.' FROM games WHERE igdb_id = 210474 ON CONFLICT (game_id, language_code) DO NOTHING;
