INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Densha de D: Lightning Stage', 'Densha de D Lighting Stage (Train D Lightning Stage) is a three dimensional train battle game based upon Initial D, a popular manga series written and illustrated by Shuichi Shigeno. The protagonist Takumi Fujiwara along with four characters of the series will return in a fast-paced arcade style racing by using densha (Japanese train). Each train compete in unique ways and the game encourage player to "powerslide" the train to keep up their speed by drifting through a turn. There are three game modes; Dramatic Mode, a single player story mode; Battle Mode, a two player battle in split screen; Replay Mode which lets player to replay their memorable battles. Densha de D Lighting Stage is the first game of the series and was released at Comiket 78, on August 14, 2010.' FROM games WHERE igdb_id = 137014 ON CONFLICT (game_id, language_code) DO NOTHING;
