INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aphelion Episode Two: Wings of Omega', 'Episode 2: Wings of Omega is the conclusion to one of the most popular RPG franchises on Xbox Live Indie. In Wings of Omega players will reprise the role of Savion Mercarte as they pick up their adventure where Episode 1: Graves of Earth left off. Savion and his allies will have to contend with enemies on two fronts as they unravel who the true orchestrator is of the attack on Earth!' FROM games WHERE igdb_id = 66165 ON CONFLICT (game_id, language_code) DO NOTHING;
