INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gloria Sinica: Han Xiongnu Wars', 'Welcome to Gloria Sinica: Han Xiongnu Wars. A stand-along game and synergy of historical Far East and multiple features in role-playing, real-time strategy and action gameplay in the Mount&Blade : Warband engine. This game brings you to the eventful years of the early Han Dynasty, and faithfully presents the ancient eastern culture with many objects and scenes faithfully reconstructed from latest archaeological findings and historic documents.' FROM games WHERE igdb_id = 67930 ON CONFLICT (game_id, language_code) DO NOTHING;
