INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shawn Johnson Gymnastics', 'Compatible with the Wii Balance Board, Shawn Johnson Gymnastics offers a truly realistic experience in the following gymnastics events: floor exercise, vault, balance beam and uneven parallel bars. Featuring the guidance and voice of Olympic gold medalist, all-round champion and "Dancing with the Stars" winner Shawn Johnson, the game invites up to eight players to train and compete in the exciting world of professional gymnastics.
