INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frogatto', 'Play as a frog in this action adventure game, with characters to talk to, things to buy, puzzles to solve, and a wide, complex world to explore. Frogatto''s key mechanic is an unusual twist; like any frog, he jumps, swims, and snags bugs with his tongue, but unlike any frog before him, can spit those bugs out with deadly force.' FROM games WHERE igdb_id = 92280 ON CONFLICT (game_id, language_code) DO NOTHING;
