INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'North American Hunting Extravaganza 2', 'The All-In-One Hunting Experience Head out into the wild once again to track and hunt the most dangerous game in North America. Become a master hunter by traveling across the country and honing your skills to go after bigger and more dangerous prey. Set your sights on over 30 different wildlife species, with a variety weapons and hunting equipment at your disposal. Hunt alone or invite your friends to compete in a variety of mini-game challenges such as fowl hunting, target shooting, and more!' FROM games WHERE igdb_id = 50619 ON CONFLICT (game_id, language_code) DO NOTHING;
