INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sydney Shark', 'The sequel to the flash game Miami Shark, Sydney Shark has players embark on another adventure in the waters of Sydney. The gameplay remains unchanged, offering the same action-packed experience of destruction and mayhem of the original game. However, Sydney Shark introduces new ways to wreak havoc by taking down helicopters carrying koalas, obliterating crocodile blimps, and intercepting nuclear missiles.' FROM games WHERE igdb_id = 275486 ON CONFLICT (game_id, language_code) DO NOTHING;
