INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sora-no-otoshimono-doki-doki-summer-vacation', 38457, '2010-06-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co72f2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1kh9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sora no Otoshimono: Doki-doki Summer Vacation', 'Tomoki Sakurai is a lad who lives in the quaint little town of Sorami. Life is quiet so Tomoki gets his kicks by being a peeping tom who has a number of prime viewing areas that he has mapped around town. Tomoki would be content to live this way forever, but one night a strange event changes his life forever. While watching the sky and waiting for two friends, from above an object falls from the heavens which turns out to be a female being known as an Angeloid. Her name is Ikaros and she sports a shock of pink hair, angel wings, and a large bosom. Ikaros bonds with Tomoki and takes him on a radical change of life experiences. The PSP game plies the interactive adventure trade which features a new story based on the animated source material. The dialogue is accompanied by speech for added ambiance. At the outset of the adventure, the somewhat mechanical song of the cicada signals the approach of summer. Once the warm weather arrives, the citizenry of Sorami visit hot springs, the beach, parks, and other locations that are amenable to lazy day lounging and sloth. It is within this backdrop that the cast of the PSP game interact, utilize card magic, and effect changes in the Angeloids that populate the adventure.' FROM games WHERE igdb_id = 38457 ON CONFLICT (game_id, language_code) DO NOTHING;
