INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Gameshow', 'Good evening and welcome to Family Gameshow! This will be the most fun you can have in front of your TV as you and your friends become contestants on the best Gameshow out there! Come and join me as you play three fantastic Gameshow formats, you can choose to play Control Freak, Hosted by Larry Lightfoot, Brain Strain, Hosted by Professor Plank or Puzzle Addict, Hosted by Tom Wordsworth. Let the show begin!' FROM games WHERE igdb_id = 51028 ON CONFLICT (game_id, language_code) DO NOTHING;
