INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LCD Dem', 'LCD Dem (Lucid Dream with some letters removed) is a Yume Nikki fangame by Japanese composer Koronba (Myspace and Bandcamp), who also was a contributor to the collaborative Nikki fangame project Yume 2kki under the name n3. The game is known for its sublime electronic music done in REAPER and atmospheres in Inkscape, centering around protagonist Chie, a young girl who, through exploring the realm of her dreams, must find and collect hidden orbs and effects, which give her special abilities.' FROM games WHERE igdb_id = 139815 ON CONFLICT (game_id, language_code) DO NOTHING;
