INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamagotchi iD Conan ver.', 'Tamagotchi iD Conan ver. is a rare, limited edition Tamagotchi iD that was given away with every subscriber issue of the Shōnen Sunday Manga Magazine, issue 3000. They have a dark blue shell and red gem. This version has characters from the Detective Conan series which players can talk to in a new destination, and Conan versions of the ID games that could be downloaded from the official website.' FROM games WHERE igdb_id = 230019 ON CONFLICT (game_id, language_code) DO NOTHING;
