INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Data Worm', 'Data Worm is a modern take on the classic video game "Snake." Set in a circular map, players navigate a digital worm that grows longer as it consumes data scattered throughout, picks up an array of power-ups and avoids obstacles in the form of viruses Unlike the traditional linear movement of the original Snake game, Data Worm offers free movement within the circular environment.' FROM games WHERE igdb_id = 281024 ON CONFLICT (game_id, language_code) DO NOTHING;
