INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'International Athletics', 'Accurate representations of 14 events: 100m, Long Jump, Shot Put, High Jump, 400m, 110m Hurdles, Discus, Pole Vault, Javelin, 1500m, Hammer, Running Target Rifle Shooting, Rapid Fire Pistol Shooting and Archery. Superior control system and character animation, and truly competitive A.I. Hugely detailed international stadiums, including venues in Canada, France, Japan, Spain and China. Single-player Decathlon, Tournament and Quick Event modes, and multiplayer modes for 2-4 players. Beat personal bests and world records, accumulate medals and earn trophies to unlock extra events and tournaments! Create your own customised male or female athlete with their own distinctive attributes. Hugely popular genre featuring intuitive Wii Remote and Nunchuk controls for instantly replayable, hugely compelling gameplay, mirroring the real events.' FROM games WHERE igdb_id = 268173 ON CONFLICT (game_id, language_code) DO NOTHING;
