INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fear for Sale: Mystery of McInroy Manor - Collector''s Edition', 'Emma Roberts has been tasked with writing a story about an old haunted manor for Fear for Sale Magazine. The estate has been locked up for years, but a sizable donation from Emma’s editor has opened up the home for exploration. Unravel the tale of the demise of the McInroy family, and set their souls free in Fear for Sale – Mystery of McInroy Manor, a dark and mysterious Hidden Object Puzzle Adventure game.' FROM games WHERE igdb_id = 125646 ON CONFLICT (game_id, language_code) DO NOTHING;
