INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Giant Moto', 'Giant Moto is a high speed, high flying racing game that''s all about the jumps, turbo boosts and scoring the best time. Giant Moto features beautiful retina display graphics, iPhone 5 widescreen support, 10 challenging tracks and 4 motorcycle''s to choose from. You can race against yourself or against 3 computer controlled bikes with 3 difficulty levels so it''s challenging and fun for kids of all ages.' FROM games WHERE igdb_id = 175572 ON CONFLICT (game_id, language_code) DO NOTHING;
