INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bibi & Tina: Das große Unwetter', 'After a devastating storm on the Martin''s Farm, Bibi and Tina have to get the badly damaged farm back in shape and prepare everything for the return of the runaway horse Finja. The storm has messed things up and so the player helps the friends Bibi and Tina to collect objects lying around, repair them and bring them back to their destination.' FROM games WHERE igdb_id = 216453 ON CONFLICT (game_id, language_code) DO NOTHING;
