INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sift Heads World: Act 2 - The Treacherous Return', 'With the Yakuza on their tail, Kiro, Vinnie and Shorty will fly to Tokyo Japan to confront a crime lord that is set on getting Kiro’s head. This new Sift Heads World episode has more of what you like; character selection, more custom costumes, plenty of new weapons and a new interactive city to explore.' FROM games WHERE igdb_id = 267159 ON CONFLICT (game_id, language_code) DO NOTHING;
