INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Durarara!! 3-way Standoff', 'In this one-player only game, you play as Yoshimune Miyoshi, a student who transfers to the same school as Kida Masaomi, Ryugamine Mikado and Sonohara Anri. You get to talk to the characters and explore Ikebukuro where the DRRR!! story is set and learn about the gangs, Dollars, Yellow Scarves and a rumoured headless rider who haunts the streets on a motorbike.' FROM games WHERE igdb_id = 66353 ON CONFLICT (game_id, language_code) DO NOTHING;
