INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Kore Gang', 'The Kore Gang is an action-adventure game where you take control of three different characters stuck inside robotic suits that amplify their individual abilities. The game-play is centered on the player''s ability to switch between the three characters at any time and thus utilize and combine their abilities to solve puzzles. The story revolves around the evil Krank Brothers, evil rulers of a civilization that exists in the center of the Earth.' FROM games WHERE igdb_id = 4960 ON CONFLICT (game_id, language_code) DO NOTHING;
