INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nobunaga''s Ambition Mobile', 'This title is a strategic historical simulation game set against the backdrop of the struggle for power played out by the mighty warlords of Warring States-era Japan. You will play as one of these warlords (daimyo), among them the revolutionary Nobunaga Oda, the "Tiger of Kai" Shingen Takeda, and the "Dragon of Echigo" Kenshin Uesugi, and fight for control of the 50 fiefdoms of ancient Japan, from Ezo in the north to Kyushu in the south.' FROM games WHERE igdb_id = 131367 ON CONFLICT (game_id, language_code) DO NOTHING;
