INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trade Nations', 'Trade Nations is a city-building simulation game where players become the mayor of a small village and grow it into a thriving nation. By harvesting resources, crafting goods, and trading with friends, players fuel their economy and unlock new buildings, decorations, and achievements. The game features a dynamic global market, social trading mechanics, and colorful animations designed for casual play.' FROM games WHERE igdb_id = 38891 ON CONFLICT (game_id, language_code) DO NOTHING;
