INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lead Wars', 'Lead Wars is a turn-based strategy war game, where unlike most turn-based games you aren’t constrained to a grid. It simulates a style of game played in the 70s and 80s, where you play on a real piece of paper and just use a pencil and your imagination to create the battlefield, units and rules of play.' FROM games WHERE igdb_id = 103076 ON CONFLICT (game_id, language_code) DO NOTHING;
