INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brunswick Zone Cosmic Bowling', 'Brunswick Zone for the Nintendo Wii captures the essence of the new "Zone", bringing the excitement, lights and music of Cosmic Bowling to your living room. Players can customize their characters and bowl through a variety of crazily-themed lanes and tricky bowling challenges. The game is easy to play thanks to Wii Remote -- you can even use the Wii MotionPlus accessory for perfectly-accurate strikes!' FROM games WHERE igdb_id = 4732 ON CONFLICT (game_id, language_code) DO NOTHING;
