INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Hive', 'In The Hive you play as Alex Rig, a reporter who was investigating a missing persons case when he discovers a heavily-fortified research facility while snooping around for clues. Similar to Iji, Prince of Persia and Flashback, Alex will be doing a lot of climbing up platforms and crawling through air vents to find ammunition or health-replenishing items that he can keep in his inventory for later use.' FROM games WHERE igdb_id = 242803 ON CONFLICT (game_id, language_code) DO NOTHING;
