INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape From the Chaotic City', 'It''s the Apocalypse! It''s an experiment! It''s just a movie! Armed just with a bat and courage, Eddy, an idle teen has to turn into a hero..in one night... But outside, on those desolates streets of Portland, the terror was released, the TV hasn''t any broadcast, the telephones are out of order... A lethal disease is running through his veins...it''s a time race... *Fight against an horde of zombies *Search for survivors *Make a plan to escape *Walk through a big city with: a hospital a mall a subway a church a bar and much more! *Reveal the dark secret behind this hell of epic game!' FROM games WHERE igdb_id = 169508 ON CONFLICT (game_id, language_code) DO NOTHING;
