INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Effing Worms', 'Effing Worms lets you play as a massive worm that''s currently underground, and is hunger for flesh. There''s only one goal in this game, and that''s to eat as much human/animal flesh as you can by jumping out from the ground - that is, before you get destroyed by their military effort to stop you from eating them.' FROM games WHERE igdb_id = 210662 ON CONFLICT (game_id, language_code) DO NOTHING;
