INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summer Challenge: Athletics Tournament', 'Summer Challenge: Athletics Tournament offers a fast-paced sports entertainment experience for the enthusiast and the entire family. Challenge the world''s best athletes in 20 disciplines playing in single or multi player game modes. Bring the excitement of major competitions into your living room with photo realistic stadiums and atmospheric sound. Summer Challenge includes the most popular and diverse sports with up to four players in head to head competition or challenge your skill in single player career mode. Compare your performance against the rest of the world via online leader boards.' FROM games WHERE igdb_id = 43012 ON CONFLICT (game_id, language_code) DO NOTHING;
