INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Party Games', 'Play exciting new and innovative games from around the globe! Each continent has its own fun and challenging games that are guaranteed to be a blast for the whole family! Curl with seals in Antarctica, race up the Eiffel Tower in France, dance for rain with African tribesman, and much more. Play on your own or, better yet, challenge up to 4 friends. Win cups and medals, unlock new levels, activate bonus levels, and don cool new threads. It''s fun for the whole family!' FROM games WHERE igdb_id = 50931 ON CONFLICT (game_id, language_code) DO NOTHING;
