INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Veggy World', 'Veggy World, an action game in which you control a strawberry-shaped spaceship that flies through broccoli-covered landscapes and turnip tree houses. Fire lasers and blue pellets at a steady wave of fruit and vegetable creatures, causing the personified food to explode in a bright burst. The depiction is mostly whimsical, though you do see their "kill percentage" tallied on menu screens at the end of each round. Game customized for each target platform.' FROM games WHERE igdb_id = 51156 ON CONFLICT (game_id, language_code) DO NOTHING;
