INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fluttabyes', 'Fluttabyes is a fun, quirky take on a Match 3 game. Easy to pick up and play, yet deeply addictive, the aim of Fluttabyes is to help the butterflies fly away by matching four or more of the same colour. The game is gorgeous and cute, with sunny countryside summer settings in a unique and colourful art style.
