INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Albatross Koukairoku', 'Aboard the Albatross is an odd captain and an equally crazy crew. With no map in hand, they sail to unknown islands, meet ghost ships and cross paths with giant monster fish. No one knows where they are heading… including the captain. But they still all stay together since there’s no other place for them.' FROM games WHERE igdb_id = 156033 ON CONFLICT (game_id, language_code) DO NOTHING;
