INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power of Defense', 'Power Of Defense provides a new strategy and defense mix game experience. Defend your world from upcoming evil and oil-smelling robots. They come from the platform between both parallel universes you have to fight on by producing own robots to send them back to their native world. You as the last hero on earth and the only one your government could find (and pay), only you can save the world.' FROM games WHERE igdb_id = 15060 ON CONFLICT (game_id, language_code) DO NOTHING;
