INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Whack Your Neighbor', 'Whack Your Neighbor is a game in the "Whack Your" series and the first by WhackIt. In this one, you have to find 32 ways (27 ways in old version) to kill your neighbor. This game introduces combo kills, which would become a staple in WhackIt''s next "Whack Your" games after this.' FROM games WHERE igdb_id = 327996 ON CONFLICT (game_id, language_code) DO NOTHING;
