INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('princess-lillifees-magic-fairy', 209890, '2010-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co74uu.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Princess Lillifee''s Magic Fairy', 'Who does not know Princess Lillifee? The sweet little princess who lives in a fairy-tale castle with a wonderful garden around it. From morning to night, Lillifee takes care of all the animals and plants that live there. She wants to be a good friend to everyone and helps them with their questions or problems. With this first Lillifee NDS game, girls of 4 step into the magical dream world of Princess Lillifee, of which they themselves always dream! Dance with Lillifee, fly with her through various fairy-tale locations. Create magic-like paintings or play magic mini-games with Lillifee. Princess Lillifee wishes all players as much happiness in life as there are stars in the sky. This Nintendo DS is aimed perfectly at the target audience of Nintendo DS players. The games can be played on both screens, with very simple touch pen navigation and voice recognition, so that the smallest girls who cannot yet read can also play this magical game. Characteristics: Dance along with Lillifee Make Princess Lilliffee beautiful with makeup and beautiful dresses Make magic paintings Awaken beautiful butterflies Play magic mini-games, such as find-the-pearls, find the match' FROM games WHERE igdb_id = 209890 ON CONFLICT (game_id, language_code) DO NOTHING;
