INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beach-buzzin-chopper', 42779, '2010-10-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7yqn.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beach Buzzin Chopper', 'You control a beach-sports chopper that is buzzin'' private beaches for bikini babes and handsome hunks. Some of the babes and hunks are already taken but others are happy to climb on board! Avoid the angered beach bodies whose squeezes you''ve stolen as they pursue you in jet packs and beach buggies armed with rubber bullets trying to get their favourite honey or dude back. If you’re successful, you get to party with the most beautiful girls or hunky guys on the beach!' FROM games WHERE igdb_id = 42779 ON CONFLICT (game_id, language_code) DO NOTHING;
