INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kotori Love Ex P', 'Kotori Love Ex P is comprised of three parts: Kotori LOVE (Kotori''s stories from D.C.P.C., D.C.W.S., D.C.A.S., and C.D.C.D.), Kotori Extasy! (18+ port of PS2 D.C.I.F.) and Kotori Plus!. The last part is a brand new story focusing on Junichi and Kotori’s life as newly-weds.' FROM games WHERE igdb_id = 139018 ON CONFLICT (game_id, language_code) DO NOTHING;
