INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where We Remain', 'Where We Remain is an adventure set on a desert island, shown from a zoomed out, almost top-down view. The content is procedurally-generated and the setup of the island is different for each session. At first glance it seems similar to the 8 and 16 bit Zelda games, but it only borrows that shape to tell its story.' FROM games WHERE igdb_id = 242922 ON CONFLICT (game_id, language_code) DO NOTHING;
