INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3-D Havok', 'Your stellar cruiser begins to shudder as the hyperwarp drive suddenly cuts out. Slowing down, you realize you''ve entered an asteroids field. A BIG asteroid field. You bolt for the high-density laser-pulse inverter. Your only chance is to blast your way out. And you better start now...' FROM games WHERE igdb_id = 11110 ON CONFLICT (game_id, language_code) DO NOTHING;
