INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Sports Football: Rookie Rush', 'The neighborhood kids hit the gridiron for a combination of football fun and crazy arcade-style twists. Get your football fix on 12 neighborhood fields and unlock items to create your own backyard. Join Dmitri, Pablo, Joey, and other favorite Backyard Kids as they welcome a rookie to the neighborhood and try to build a winner in an all-new Story Mode. Use wacky power-ups like Deep Freeze and Banana Peels, work on skills in new mini-games, compete in tournaments, and more.' FROM games WHERE igdb_id = 47408 ON CONFLICT (game_id, language_code) DO NOTHING;
