INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Older', 'Older is a traditional Yume Nikki fangame. The game stars Takashi and is centered around the collection of effects and exploration of a dream world. The game allows saving through the menu, but is primarily done through a typewriter in Takashi''s room. Uniquely, the dream world is accessed through a projector.' FROM games WHERE igdb_id = 166351 ON CONFLICT (game_id, language_code) DO NOTHING;
