INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Rancher DS', 'Raise, Train and Battle your monsters in Monster Rancher DS, the newest addition to the beloved breeding series. Filled with nostalgia from past games, fans of the series will recognize popular characters and monsters such as Mocchi and Suezo, in addition to new monsters to discover. Generate monsters by drawing pictures in the "magic Field," or by speaking into the microphone in "Incantation" mode. Use your best strategy to raise, train, and battle your monsters. Can you become a legendary master breeder?' FROM games WHERE igdb_id = 47795 ON CONFLICT (game_id, language_code) DO NOTHING;
