INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Techno Trancer', 'Listen in amazement as music syncs with dazzling action in this pulse-pumping, high-speed shooting game! In addition to the current 2 modes, a hidden AWAKEN MODE has been added! Use your awakened might to evade over 10 times the normal onslaught of enemy fire! 2 exciting new music tracks have also been added!' FROM games WHERE igdb_id = 197996 ON CONFLICT (game_id, language_code) DO NOTHING;
