INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Let''s Play Ballerina', 'Ballet and the grand beauty of the theater have captured the hearts of young girls for generations. Now, in Let''s Play Ballerina, every girl can live out their fantasy of becoming prima ballerina and lead some of the world''s most famous ballet performances, from the Nutcracker to Swan Lake and beyond. The player takes on the role of a 12 year old girl starting out at a renowned ballet school. Through training, the player will learn dance perfection with new steps and following the rhythm of music. They’ll also encounter fun friends and experience the drama of being at one of the world’s best schools of ballet!' FROM games WHERE igdb_id = 51068 ON CONFLICT (game_id, language_code) DO NOTHING;
