INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidden Expedition: Everest', 'Fresh from a successful exploration of the wreck of the Titanic, the Hidden Expedition Club will pit one of its stellar members against a formidable group of opponents in a race to the summit of Everest. Other groups will battle you to be the first to summit Mount Everest. Expert Everest climber Ed Viesturs will assist you along the way. Explore mysteries of the world as you find hidden clues. Race to the Roof of the World!' FROM games WHERE igdb_id = 16177 ON CONFLICT (game_id, language_code) DO NOTHING;
