INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'K11: Kommissare im Einsatz', 'Slip into the role of a young inspector who is new to the K11 team and solve five exciting and tricky cases under the guidance of inspectors Rietz and Naseband. Experience the thrill of a real investigator in a world full of intrigue and lies and try to uncover the truth against all odds. Investigate crime scenes with the typical technical tools of a modern investigator. Rely on your judgment as you sit in the interrogation room with both yourselves and suspects and only through skillful interrogation can you get them to reveal their most secret thoughts.' FROM games WHERE igdb_id = 268183 ON CONFLICT (game_id, language_code) DO NOTHING;
