INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DoDonPachi Daifukkatsu Black Label', 'DoDonPachi DaiFukkatsu Black Label is a revamped version of the original DoDonPachi DaiFukkatsu, with new mechanics and a brand new soundtrack. It features much of the same structure of DaiFukkatsu, but with a few crucial differences, notably, the game only has one loop, and now features a player-controller rank system (known as Red Mode). This version is programmed by Shinobu Yagawa.' FROM games WHERE igdb_id = 77997 ON CONFLICT (game_id, language_code) DO NOTHING;
