INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('motorm4x-offroad-extreme', 50767, '2010-07-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2f3t.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Motorm4x: Offroad Extreme', 'Em MOTORM4X: ATVs extremas jogador se senta ao volante de um carro e unidades de cross-country em condições extremamente difíceis. O objetivo é chegar a um destino previamente designados. O que torna este jogo diferente dos outros do mesmo gênero é uma completa liberdade para escolher a rota, mesmo que isso signifique dirigir em todos os tipos de terreno. É unicamente a decisão do jogador que caminho tomar. O jogador pode escolher entre dez veículos 4WD. Os criadores projetaram quatro tipos de corridas. "Raça" é uma competição por turnos em que o vencedor é a pessoa que cruza a linha de chegada em primeiro lugar. "Longrun" é um comício contra-relógio. "Pathfinder" dá-lhe a oportunidade de escolher qualquer rota no caminho para o seu destino. "Trial" é semelhante, mas nesta corrida as condições são bastante extremas.
