INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GTI Club Supermini Festa!', 'GTI Club Supermini Festa! is based on the latest arcade iteration of the long-running series, and charges the player with racing a series of compact cars around a series of citiscapes across France, the UK, Italy, the US, and Japan. Everything about the game is geared towards searing speed and intuitive handling, with players tussling with CPU-controlled cars or their friends through busy streets as they attempt to be the first past the winning line.' FROM games WHERE igdb_id = 50961 ON CONFLICT (game_id, language_code) DO NOTHING;
