INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carnage Heart EXA', 'A follow-up to the cult classic, Carnage Heart EXA puts players in control of giant robots - Overkill Engines (OKEs) - and pits these menacing mechs against each other in larger-than-life battles! You can control your OKE yourself or set up complex programs that automatically command your robo-battlers to follow your orders to the letter. Choose from either a compelling Story Mode, or get right into the action with Battle Mode!' FROM games WHERE igdb_id = 46589 ON CONFLICT (game_id, language_code) DO NOTHING;
