INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snoopy Flying Ace', 'You can''t have aerial dogfighting without the dog! Join Snoopy, Charlie Brown, and the rest of the Peanuts gang in the premier online flight shooter on Xbox LIVE Arcade, Snoopy Flying Ace. With simple flight controls and a hangar full of customizable planes and weapons, all you need are nerves of steel to climb the Leaderboards and become a Flying Ace! Snoopy Flying Ace takes addictive, fast-paced airborne combat to new heights, with fantastic solo and co-op challenges testing your skills against the Flying Circus of the dreaded Red Baron. Remember, it ain''t the size of the dog in the fight … it''s the size of the fight in the dog!' FROM games WHERE igdb_id = 21887 ON CONFLICT (game_id, language_code) DO NOTHING;
