INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ace Armstrong vs. The Alien Scumbags!', 'Ace Armstrong vs. the Alien Scumbags! is a fast-paced horizontally scrolling shooter with a unique, slapstick take on the best of 50s and 60s sci-fi movies and cartoons. The game features a unique weapons system: instead of collecting power-ups, Ace must down enemies using the incredible power of the Recyl-o-Ray! before turning the Scumbags’ own weapons against them!
