INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aero Racer', 'Take to the sky-high tracks with speed and precision in Rocket Racing, which challenges your reflexes and daring across 24 levels in Grand Prix, Challenge and Quick Race events. Drive like a true prodigy by mastering advanced drifting and wall-boosting techniques to get an edge over your opponents and achieve record times. Rocket Racing is intense action from the green light to the finish line!' FROM games WHERE igdb_id = 42833 ON CONFLICT (game_id, language_code) DO NOTHING;
