INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battle-of-giants-dinosaurs-strike--1', 7907, '2010-11-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zf8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9gtj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle of Giants: Dinosaurs Strike', 'Ubisoft''s fighting series designed for boy gamers aged six to ten comes to the Wii for the first time with more mighty clashes between some of the most powerful and ferocious creatures to ever roam the earth in Battle of Giants: Dinosaurs Strike. Gamers select from a group of 18 different dinosaur breeds, including T-Rex, Velociraptor, and Stegasaurus, and then choose from 12 different colors and patterns. Players use their Wii Remote and Nunchuk to battle opponents in three-round bouts, taking advantage of each dinosaur''s particular strengths and weaknesses. Those who win are rewarded with bonuses that unlock thorns, bones, and feathers to make their creatures stronger, tougher, and faster. In addition to battling fellow dinosaurs, combatants must also avoid taking damage from cataclysmic events plaguing the forest, desert, and mountain environments. Solo gamers can also take on the ladder-style "Domination" mode, while multiplayer fans can join up to three friends for the "Versus," "Tournament," and Tag Team" modes.' FROM games WHERE igdb_id = 7907 ON CONFLICT (game_id, language_code) DO NOTHING;
