INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hegemony: Philip of Macedon', 'Hegemony: Philip of Macedon lets you conquer the ancient Greek world in this PC RTS war game that follows the rise of Philip of Macedon, father of Alexander the Great. Players campaign across a continuous satellite-accurate map of ancient Greece encountering the full range of warfare from reconnaissance to raids to field battles to mountain blockades.' FROM games WHERE igdb_id = 11523 ON CONFLICT (game_id, language_code) DO NOTHING;
