INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blade Buster', 'Blade Buster is a new homebrew NES shoot ’em up by the doujin group High Level Challenge. The game is based on the two time attack modes from the 1990 Turbografx-16 vertical shoot ’em up Super Star Soldier, in which you try to achieve the highest possible score in either 2 or 5 minutes. So there are only two short stages in the game, with the boss battles at the end of each one. Aside from the standard enemies, boxes, and gems, there are various hidden bonuses you can get for extra points.' FROM games WHERE igdb_id = 48316 ON CONFLICT (game_id, language_code) DO NOTHING;
