INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Delaware St. John: Volume 3 - The Seacliff Tragedy', 'The sound of a hundred voices call to Delaware St. John and lead him to the site of a decrepit amusement park. The site closed four years earlier after a collapse killed more than a hundred people. As Delaware explores the area he discovers the tragic accident is only the beginning of the dark events taking place. Delaware St. John: Seacliff Tragedy is an adventure game full of suspense and excitement.' FROM games WHERE igdb_id = 71352 ON CONFLICT (game_id, language_code) DO NOTHING;
