INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('darkstar-the-interactive-movie', 9118, '2010-11-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cggbr30v0dhflevpqodc.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkstar: The Interactive Movie', 'In this tale of murder and deception with nothing less than the fate of humanity at stake, you awaken inside a cryogenic sleep chamber aboard the drifting starship, Westwick. As Captain John O''Neil, you are physically unharmed, but suffer from a complete and permanent loss of memory. Beside you are three other sleep chambers. One is empty. In another lies a beautiful woman, still in hibernation. The final chamber contains a 300-year old corpse. The ship''s computer, Westwick Main, has also had much of her memory deleted by someone unknown. Your wits are your greatest weapon in this story of suspense and interplanetary intrigue. Nothing is as it seems and despite the icy, cold silence... you''re not alone.' FROM games WHERE igdb_id = 9118 ON CONFLICT (game_id, language_code) DO NOTHING;
