INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tork and Kral', 'Tork and Kral is a platform game similar to Mario Bros., with an ice age setting. The players have to kill all enemies in each level to complete it. The levels are stationary and the screen will only scroll vertically when the player climbs over the upper platforms. Some enemies move about the level (like dinosaurs, bears and bats) while others are stationary (like spore plants and snowmen). In some levels there are eggs which will spawn enemies regularly until destroyed.' FROM games WHERE igdb_id = 98128 ON CONFLICT (game_id, language_code) DO NOTHING;
